const uor01Text = $('Extract UOR-01 Text').first().json.data || '';
const uor06Text = $('Extract UOR-06 Text').first().json.data || '';

function parseLines(text) {
  const out = [];
  let failures = 0;
  text.split('\n').filter((l) => l.trim().length > 0).forEach((line) => {
    try { out.push(JSON.parse(line)); } catch (e) { failures++; }
  });
  return { records: out, failures };
}

const uor01 = parseLines(uor01Text);
const uor06 = parseLines(uor06Text);

const tagMembers = {
  freelance_gig_service_demand: new Set(),
  lead_gen_qualification: new Set(),
  customer_communication_automation: new Set(),
};
uor06.records.forEach((row) => {
  if (tagMembers[row.tag]) {
    (row.member_opportunity_ids || []).forEach((id) => tagMembers[row.tag].add(id));
  }
});

function keywordRegex(term, exact) {
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return exact ? new RegExp(`\\b${escaped}\\b`, 'i') : new RegExp(`\\b${escaped}\\w*`, 'i');
}

const SERVICE_KEYWORDS = [
  ['freelancer',false],['contractor',false],['consultant',false],['will pay',true],
  ['hire',false],['outsource',false],['need someone',true],['looking for a developer',true],
  ['looking for someone',true],['/hr',true],['rate of',true],
];

function extractDollarAmounts(text) {
  const matches = text.match(/\$\s?[0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?(?:\/hr|\/hour|\/month|k)?/gi);
  return matches ? [...new Set(matches.map((m) => m.trim()))] : [];
}

const results = uor01.records.map((rec) => {
  const rs = rec.raw_signal || {};
  const text = `${rs.opportunity_title || ''} ${rs.problem || ''} ${rs.demand_signal || ''}`;
  const keywords = SERVICE_KEYWORDS.filter(([t, e]) => keywordRegex(t, e).test(text)).map(([t]) => t);
  const dollarAmounts = extractDollarAmounts(text);
  const membership = {
    freelance_gig_service_demand: tagMembers.freelance_gig_service_demand.has(rec.opportunity_id),
    lead_gen_qualification: tagMembers.lead_gen_qualification.has(rec.opportunity_id),
    customer_communication_automation: tagMembers.customer_communication_automation.has(rec.opportunity_id),
  };
  const anyTag = membership.freelance_gig_service_demand || membership.lead_gen_qualification || membership.customer_communication_automation;

  let service_opportunity_status;
  if (keywords.length > 0) service_opportunity_status = 'GENUINE_SERVICE_SEEKING_SIGNAL';
  else if (anyTag) service_opportunity_status = 'WEAK_TANGENTIAL_MENTION';
  else service_opportunity_status = 'NO_SERVICE_SIGNAL_DETECTED';

  const factors = rec.scoring_factors || {};
  const autoEstimateRaw = factors.automation_potential?.estimate;
  const automation_potential_pct = typeof autoEstimateRaw === 'number' ? autoEstimateRaw * 10 : null;

  return {
    opportunity_id: rec.opportunity_id,
    service_seeking_keywords_matched: keywords,
    stated_dollar_amounts: dollarAmounts,
    uor06_tag_membership: membership,
    service_opportunity_status,
    automation_potential_pct,
    formula_version: 'uor08-v1-service-signal-2026-09-06',
    computed_at: new Date().toISOString(),
  };
});

const fileText = results.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    uor01_record_count: uor01.records.length,
    uor01_parse_failures: uor01.failures,
    uor06_record_count: uor06.records.length,
    uor06_parse_failures: uor06.failures,
    status_breakdown: results.reduce((acc, r) => { acc[r.service_opportunity_status] = (acc[r.service_opportunity_status]||0)+1; return acc; }, {}),
    file_text: fileText,
  },
}];
